  // Combat model (hits-to-kill):
  // Ammo out of the shooter sets raw damage (faction dmg × weapon mul × tier).
  // Target hull + shield set effective HP; armor plating mitigates hull hits.
  // Yardstick: one Pulse shot from a T1 ADA gun ≈ 14 dmg. HIT_BUDGET[tier] =
  // how many of those Pulse hits should empty a same-tier foe (shield+hull).
  const REF_PULSE_DMG = 14;
  const HIT_BUDGET = [0, 5.0, 6.5, 8.0, 10.0, 12.5, 15.0, 18.0];

  function enemyCombatPools(faction, tier) {
    const def = SHIPS[faction] || SHIPS.ada;
    const t = clamp(tier || 1, 1, 7);
    const T = tierDef(t);
    const bias = (def.hull + def.shield * 0.7) / (120 + 90 * 0.7); // ADA ≈ 1
    const ehp = HIT_BUDGET[t] * REF_PULSE_DMG * clamp(bias, 0.72, 1.5) * (0.92 + 0.08 * T.hull);
    const denom = Math.max(1, def.hull + def.shield);
    const shieldFrac = clamp(def.shield / denom, 0.18, 0.55);
    const maxShield = ehp * shieldFrac;
    const maxHull = Math.max(12, ehp - maxShield);
    return { maxHull: maxHull, maxShield: maxShield, armorClass: t };
  }

  function armorMitigate(ship, dmg, layer) {
    if (!ship || dmg <= 0) return dmg;
    let plate = 0;
    if (ship.player) {
      if (layer === "hull") plate = (G.lootArmorClass || 0) * 0.06;
      else if (layer === "shield") plate = (G.lootShieldClass || 0) * 0.05;
    } else {
      // Enemy plating scales with tier / hung armorClass
      const ac = ship.armorClass != null ? ship.armorClass : (ship.tier || 1);
      if (layer === "hull") plate = Math.max(0, (ac - 1) * 0.045);
      else if (layer === "shield") plate = Math.max(0, (ac - 1) * 0.025);
    }
    return dmg * (1 - clamp(plate, 0, 0.38));
  }

