  function tickPilotVitals(dt, where) {
    if (!(dt > 0)) return;
    ensureVitals();
    // street ~1.2 fed/min, flight ~2/min; alert ~0.8/min, ~2.5 when boosting/hurt
    const fedRate = (where === "flight") ? (2 / 60) : (1.2 / 60);
    let alertRate = 0.8 / 60;
    if (where === "flight" && G.player && !G.player.dead) {
      if (G.player.boosting || (G.player.hurt || 0) > 0) alertRate = 2.5 / 60;
    }
    G.vitals.fed = clamp(G.vitals.fed - fedRate * dt, 0, 100);
    G.vitals.alert = clamp(G.vitals.alert - alertRate * dt, 0, 100);
  }
  function tryFuelSip(source) {
    ensureVitals();
    const p = G.player;
    const sk = shopSnackSpec({ shopType: "fuel" });
    const cost = shopSnackCostAda(sk);
    const need = !(G.freeFuelOnce);
    if (need && (G.credits || 0) < cost) {
      dockSay("Need " + money(cost) + " for a sip, you have " + money(G.credits));
      return false;
    }
    let free = false;
    if (G.freeFuelOnce) {
      G.freeFuelOnce = false;
      free = true;
    } else {
      credit(-cost, (sk && sk.item) || "Sip of juice", "fuel pump");
    }
    if (p && !p.dead) {
      p.energy = p.maxEnergy;
    }
    const here = planetById(G.lastDock) || planetById(MARKET.planetId) || PLANETS[0];
    const tag = (here && here.name) || "Harbor";
    const line = free
      ? (tag + " pump — scoop covered the sip. Banks full.")
      : (tag + " pump — banks full. " + ((sk && sk.msg) || "Tastes like a rumor."));
    toast(line);
    dockSay(line);
    pickupSnd();
    paintMarketHud();
    try { updateHud(); } catch (e) {}
    saveGame();
    return true;
  }
  function heatScore() { return G.outlaw | 0; }
  function heatHot() { return heatScore() >= 20 || !!G.heat; }
  function paintHeat() {
    const el = $("heatTxt");
    if (!el) return;
    const n = heatScore();
    el.className = "heat";
    if (n <= 0) { el.textContent = ""; return; }
    if (n >= 70) { el.textContent = "BURNING " + n; el.classList.add("heat-burn"); }
    else if (n >= 45) { el.textContent = "WANTED " + n; el.classList.add("heat-wanted"); }
    else if (n >= 20) { el.textContent = "HEAT " + n; el.classList.add("heat-hot"); }
    else { el.textContent = "HEAT " + n; el.classList.add("heat-mute"); }
  }
  function addHeat(n) {
    const prev = heatScore();
    n = +n || 0;
    if (hasTrait("coolvisor")) n *= 0.75;
    G.outlaw = clamp((G.outlaw || 0) + n, 0, 100);
    const now = heatScore();
    if (prev < 70 && now >= 70) toast("BURNING — they won't look away.");
    else if (prev < 45 && now >= 45) toast("WANTED — hunters will stick.");
    else if (prev < 20 && now >= 20) toast("Heat's on you.");
    paintHeat();
    return now;
  }
  function coolHeat(n) {
    n = +n || 0;
    if (hasTrait("coolvisor")) n *= 1.25;
    G.outlaw = clamp((G.outlaw || 0) - n, 0, 100);
    paintHeat();
    return heatScore();
  }
  function tierMult(m) {
    const t = Math.max(1, G.tier || 1);
    const k = (m && m.finale) ? 1.5 : 0.32;
    return 1 + k * (t - 1);
  }
  function contractPay(m) {
    return (m && m.pay ? m.pay : 0) * tierMult(m) * payScale();
  }

