  const ROCKY_WORLD = { bitcoin: 1, litecoin: 1, avalanche: 1, doge: 1 };
  const GASSY_WORLD = { ethereum: 1, ripple: 1 };
  const HALO_DASH = [5, 9];
  const HALO_SOLID = [];
  const ADDR_CRUMB = {
    cardano: "addr1qx…₳", bitcoin: "bc1q7k…", ethereum: "0x7f3a…", solana: "So1ana…",
    polkadot: "15oF4…", doge: "D7Y55…", ripple: "rHb9C…", cosmos: "cosmos1…",
    litecoin: "ltc1q…", avalanche: "0xAVA…"
  };
  const PLANET_LOOK = Object.create(null);
  const ATM_GLOW = { cardano: "rgba(0,195,255,0.32)", bitcoin: "rgba(247,147,26,0.2)", ethereum: "rgba(139,124,255,0.3)", solana: "rgba(20,241,149,0.26)", polkadot: "rgba(140,70,100,0.16)", doge: "rgba(194,166,51,0.26)", ripple: "rgba(0,165,224,0.3)", cosmos: "rgba(120,140,200,0.28)", litecoin: "rgba(166,169,170,0.26)", avalanche: "rgba(232,65,66,0.28)" };
  function seedPlanetLooks() {
    let seed = 0;
    function rnd() {
      seed |= 0;
      seed = seed + 0x6D2B79F5 | 0;
      let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    }
    function seedFrom(id) {
      seed = 2166136261;
      for (let i = 0; i < id.length; i++) { seed ^= id.charCodeAt(i); seed = Math.imul(seed, 16777619); }
      seed >>>= 0;
    }
    for (const pl of PLANETS) {
      seedFrom(pl.id);
      const rocky = !!ROCKY_WORLD[pl.id];
      const gassy = !!GASSY_WORLD[pl.id];
      const n = gassy ? 4 + (rnd() * 2 | 0) : rocky ? 8 + (rnd() * 3 | 0) : 5 + (rnd() * 3 | 0);
      const craters = [];
      for (let i = 0; i < n; i++) {
        const a = rnd() * 6.283185307179586;
        const d = 0.16 + rnd() * 0.7;
        craters.push({
          x: Math.cos(a) * d,
          y: Math.sin(a) * d,
          r: (rocky ? 0.07 : gassy ? 0.04 : 0.052) + rnd() * (rocky ? 0.088 : 0.052),
          deep: rocky ? 0.5 + rnd() * 0.32 : gassy ? 0.14 + rnd() * 0.16 : 0.28 + rnd() * 0.22,
          swirl: gassy ? 0.55 + rnd() * 0.45 : (rnd() < 0.16 ? 0.22 : 0),
          tilt: rnd() * 6.283185307179586
        });
      }
      const bits = [];
      const nb = pl.id === "cosmos" ? 6 : (gassy ? 7 : rocky ? 10 : 8);
      for (let i = 0; i < nb; i++) {
        bits.push({
          a0: rnd() * 6.283185307179586,
          rad: 1.05 + rnd() * 0.34,
          s: 1.15 + rnd() * 2.4,
          sp: 0.2 + rnd() * 0.58,
          ph: rnd() * 6.283185307179586,
          k: i,
          squash: 0.64 + rnd() * 0.26
        });
      }
      PLANET_LOOK[pl.id] = { craters: craters, bits: bits, hexA: rnd() * 6.28, scanRot: rnd() * 0.7 - 0.35 };
    }
  }
  seedPlanetLooks();

