  let W = 1280, H = 720, dpr = 1;
  function resize() {
    dpr = Math.min(2, window.devicePixelRatio || 1);
    W = window.innerWidth; H = window.innerHeight;
    canvas.width = (W * dpr) | 0; canvas.height = (H * dpr) | 0;
    canvas.style.width = W + "px"; canvas.style.height = H + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener("resize", resize);
  resize();

  function isFullscreen() {
    return !!(document.fullscreenElement || document.webkitFullscreenElement);
  }
  function goFullscreen() {
    const el = document.documentElement;
    const req = el.requestFullscreen || el.webkitRequestFullscreen;
    if (!req || isFullscreen()) return;
    const p = req.call(el);
    if (p && p.catch) p.catch(function () {});
  }
  function toggleFullscreen() {
    if (isFullscreen()) {
      const exit = document.exitFullscreen || document.webkitExitFullscreen;
      if (exit) { const p = exit.call(document); if (p && p.catch) p.catch(function () {}); }
    } else goFullscreen();
  }
  document.addEventListener("fullscreenchange", resize);
  document.addEventListener("webkitfullscreenchange", resize);

  const audio = { ctx: null, muted: false, sirenCd: 0 };
  function audioCtx() {
    if (!audio.ctx) audio.ctx = new (window.AudioContext || window.webkitAudioContext)();
    if (audio.ctx.state === "suspended") audio.ctx.resume();
    return audio.ctx;
  }
  function beep(freq, dur, type, vol, slide) {
    if (audio.muted) return;
    try {
      const ac = audioCtx();
      const o = ac.createOscillator();
      const g = ac.createGain();
      o.type = type || "square";
      o.frequency.value = freq;
      if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(40, slide), ac.currentTime + dur);
      g.gain.value = vol || 0.06;
      g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime + dur);
      o.connect(g); g.connect(ac.destination);
      o.start(); o.stop(ac.currentTime + dur);
    } catch (e) {}
  }
  function boom() { beep(140, 0.35, "sawtooth", 0.09, 40); beep(70, 0.4, "triangle", 0.07, 30); }
  function pew(f) { beep(f || 520, 0.08, "square", 0.05, (f || 520) * 1.6); }
  function whoosh() { beep(90, 0.18, "sawtooth", 0.03, 220); }
  function chime() { beep(660, 0.12, "sine", 0.05); setTimeout(() => beep(880, 0.14, "sine", 0.04), 80); }
  function pickupSnd() { beep(880, 0.08, "sine", 0.05, 1400); }
  function siren() {
    if (audio.muted) return;
    beep(390, 0.2, "sawtooth", 0.05, 720);
    setTimeout(() => beep(720, 0.2, "sawtooth", 0.045, 360), 180);
    setTimeout(() => beep(480, 0.16, "triangle", 0.035, 800), 380);
  }

