    const used = AP_MKT.exploreT || 0;
    const budget = AP_MKT.lingerBudget != null ? AP_MKT.lingerBudget : exploreLingerBudget(ex);
    if (ex <= 0 || used >= budget) return false;
    if (typeof apLoupePending === "function" && apLoupePending()) return false;
    if (typeof apPlanetNeedsCrumb === "function" && apPlanetNeedsCrumb(MARKET.planetId || G.lastDock || "")) return false;
    if (ex >= 11) return true;
