  function cafeDrinkCost(d) {
    // Drink `cost` fields are USD catalog; convert live like hulls/inv.
    let usd = d && (d.usd != null ? d.usd : d.cost);
    if (!(usd > 0)) usd = 4;
    if (hasTrait("cafefirst") && !G.cafeFirstSip) usd = Math.max(1, usd - 2);
    return usdToAda(usd);
  }
  function buyCafeDrink(id) {
    const d = cafeDrinkById(id);
    if (!d) return false;
    const cost = cafeDrinkCost(d);
    if ((G.credits || 0) < cost) {
      dockSay("Need " + money(cost) + ", you have " + money(G.credits));
      return false;
    }
    credit(-cost, d.name, "cantina");
    if (hasTrait("cafefirst") && !G.cafeFirstSip) G.cafeFirstSip = 1;
    ensureStamp();
    if (!G.stamp.cafeSip) {
      G.stamp.cafeSip = true;
      if ((MARKET.planetId || "") === "cardano") toast("Curtain twitched. Something behind the booth wants a look.");
    }
    MARKET.servedCup = { id: d.id, steam: 5.2 };
    MARKET.clerkServe = 1.4;
    MARKET.playerCup = { id: d.id, hold: 8, sipped: false, sip: d.sip };
    ensureVitals();
    G.vitals.fed = Math.min(100, G.vitals.fed + 45);
    G.vitals.alert = Math.min(100, G.vitals.alert + 28);
    if (d.buff === "padfee") {
      G.freeFuelOnce = true;
      toast(d.serve || "Settle Steam — next pad fee rumor waived");
    } else if (d.buff && d.buff !== "cosmetic") {
      G.cafeBuffKind = d.buff;
      G.cafeBuffT = Math.max(G.cafeBuffT || 0, d.buffT || 40);
      toast(d.serve || (d.name + " · tiny buff, don't brag"));
    } else {
      toast(d.serve || d.name);
    }
    dockSay(d.serve);
    pickupSnd();
    if (MARKET.kiosk) {
      if ($("kioskScreen")) $("kioskScreen").textContent = d.serve;
      paintCafeKioskMenu();
    }
    if (MARKET.talk) paintTalkCard(MARKET.talk);
    paintMarketHud();
    saveGame();
    return true;
  }
  function paintCafeKioskMenu() {
    const el = $("kioskMenu");
    if (!el) return;
    el.innerHTML = "";
    cafeDrinks().forEach(function (d) {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "kiosk-drink";
      btn.setAttribute("data-act", "cafedrink");
      btn.setAttribute("data-id", d.id);
      btn.textContent = d.name.toUpperCase() + "  ·  " + money(cafeDrinkCost(d));
      el.appendChild(btn);
    });
  }

  function apBuySnack(stall) {
    if (!stall || stall.kind !== "shop") return false;
    if (shopKind(stall) === "cafe") return buyCafeDrink("sludge");
    if (shopKind(stall) === "fuel") return tryFuelSip("ap");
    const sk = shopSnackSpec(stall);
    const cost = shopSnackCostAda(sk);
    if ((G.credits || 0) >= cost) {
      credit(-cost, sk.item, "market snack");
      ensureVitals();
      G.vitals.fed = Math.min(100, G.vitals.fed + 8);
      pickupSnd();
      dockSay(sk.msg);
      paintMarketHud();
      saveGame();
      return true;
    }
    return false;
  }

