  function souvenirHoldStock() {
    const pid = MARKET.planetId || G.lastDock || "cardano";
    let pool = (INV_STREET_BY_PLANET[pid] || []).slice();
    if (!pool.length) {
      // planet-weighted fallbacks when street table is thin
      const fb = {
        solana: ["mempool_ticket", "scout_postcard"],
        polkadot: ["validator_fob", "scout_postcard"],
        ripple: ["cold_usb", "scout_postcard"],
        litecoin: ["hash_stamp", "scout_postcard"],
        doge: ["doge_stickers", "scout_postcard"]
      };
      pool = (fb[pid] || ["scout_postcard", "tomato_can"]).slice();
    }
    const out = [];
    const seen = {};
    for (let i = 0; i < pool.length && out.length < 2; i++) {
      const id = pool[i];
      if (!id || seen[id] || !invCatalog(id)) continue;
      seen[id] = true;
      out.push(id);
    }
    if (!out.length && invCatalog("scout_postcard")) out.push("scout_postcard");
    return out;
  }
  function souvenirHoldHtml() {
    const ids = souvenirHoldStock();
    if (!ids.length) return "";
    let html = "<div class='tag'>HOLD LOCKER</div>";
    for (let i = 0; i < ids.length; i++) {
      const c = invCatalog(ids[i]);
      if (!c) continue;
      const costAda = usdToAda(c.usd);
      html += "<div class='upg'>" + c.name + " · " + c.mass + "u";
      html += " <button type='button' data-act='buyinv' data-id='" + c.id + "'>HOLD · " + moneyUsd(costAda) + "</button></div>";
    }
    return html;
  }
  function buySouvenirInv(id) {
    const c = invCatalog(id);
    if (!c) { toast("Locker empty."); return false; }
    const cost = usdToAda(c.usd);
    if ((G.credits || 0) < cost) {
      dockSay("Need " + moneyUsd(cost) + ", you have " + moneyUsd(G.credits));
      return false;
    }
    const it = makeInvItem(id);
    if (!it) return false;
    if (!pushCargoItem(it)) {
      toast("Hold full — empty a kit first");
      return false;
    }
    credit(-cost, c.name, "keeps hold");
    toast(c.name + " into the hold. Drawer tax unpaid.");
    pickupSnd();
    if (MARKET.talk) paintTalkCard(MARKET.talk);
    paintMarketHud();
    if (isInvOpen()) paintInventoryPanel();
    saveGame();
    return true;
  }
  function flavorShopTalk(stall) {
    const spec = stall.shopType || "souvenir";
    const sk = shopSnackSpec(stall);
    const tag = { meme: "MEMES CART", cafe: "CANTINA", fuel: "PUMP", souvenir: "KEEPS", sand: "SAND KEEP" }[spec] || "SHOP";
    let html = "<div class='tag'>" + tag + "</div><h3>" + stall.name + "</h3>";
    html += "<p>" + (stall.blurb || "Lane talk.") + "</p>";
    html += clerkLineHtml();
    html += "<div class='talk-actions'>";
    html += talkBtnHtml();
    if (spec === "cafe") {
      cafeDrinks().forEach(function (d) {
        html += "<button type='button' data-act='cafedrink' data-id='" + d.id + "'>" + d.name.toUpperCase() + "  ·  " + money(cafeDrinkCost(d)) + "</button>";
      });
    } else {
      html += "<p class='talk-pay'>" + sk.item + "  ·  " + moneyUsd(shopSnackCostAda(sk)) + "</p>";
      html += "<button type='button' data-act='snack' data-cost='" + shopSnackCostAda(sk) + "' data-item='" + sk.item + "' data-msg='" + sk.msg + "'>BUY " + moneyUsd(shopSnackCostAda(sk)) + "</button>";
      const toy = shopToySpec(stall);
      if (toy) html += "<button type='button' data-act='roomtoy'>" + toy.verb + "</button>";
      if (spec === "souvenir" || spec === "meme" || spec === "sand") html += souvenirHoldHtml();
    }
    html += "</div>";
    return html;
  }

  function funnyHash() {
    const hex = "0123456789abcdef";
    let out = "0x";
    for (let i = 0; i < 12; i++) out += hex[(Math.random() * 16) | 0];
    return out;
  }
  function nextRoomQuote(kind, lines) {
    const here = planetById(G.lastDock);
    const fl = FLARE_LINES[(here && here.id) || "cardano"] || [];
    if (fl.length && Math.random() < 0.28) return pick(fl);
    if (!lines || !lines.length) return "";
    if (!MARKET.quoteSeen) MARKET.quoteSeen = {};
    let seen = MARKET.quoteSeen[kind];
    if (!seen) seen = MARKET.quoteSeen[kind] = [];
    if (seen.length >= lines.length) seen.length = 0;
    const unused = [];
    for (let i = 0; i < lines.length; i++) if (seen.indexOf(i) < 0) unused.push(i);
    const pickI = unused[(Math.random() * unused.length) | 0];
    seen.push(pickI);
    return lines[pickI];
  }
