  function doRoomToy(stall) {
    const toy = shopToySpec(stall);
    if (!toy) return false;
    // Fuel HASH/PUMP: real ship energy refill (paid sip unless freeFuelOnce).
    if (toy.id === "fuel" || shopKind(stall) === "fuel") {
      if (!tryFuelSip("toy")) return false;
      let line = nextRoomQuote(toy.id || "fuel", toy.lines);
      if (toy.hash) line = line + "  " + funnyHash();
      MARKET.toyFx = { t: 1.4, kind: "fuel", line: line };
      beep(640, 0.05, "square", 0.04);
      setTimeout(function () { beep(880, 0.04, "sine", 0.03); }, 80);
      if (MARKET.talk === stall) paintTalkCard(stall);
      return true;
    }
    let line = nextRoomQuote(toy.id || (stall && (stall.shopType || stall.kind)) || "shop", toy.lines);
    if (toy.hash) line = line + "  " + funnyHash();
    if (toy.ledger) {
      ledgerAdd("payload · " + line.slice(0, 36), 0, "funny tx");
    }
    MARKET.toyFx = { t: 1.4, kind: toy.id, line: line };
    if (toy.id === "meme") {
      const lab = pick(MEME_LABELS);
      MARKET.memeShot = { label: lab, line: line, at: G.time || 0 };
      ensureVitals();
      G.vitals.alert = Math.min(100, G.vitals.alert + 8);
    }
    if (toy.id === "loft" || shopKind(stall) === "loft") {
      if (!MARKET.loftTuneDone) {
        MARKET.loftTuneDone = true;
        ensureVitals();
        G.vitals.alert = Math.min(100, G.vitals.alert + 12);
      }
    }
    dockSay(line);
    toast(line);
    beep(640, 0.05, "square", 0.04);
    setTimeout(function () { beep(880, 0.04, "sine", 0.03); }, 80);
    if (toy.id === "meme") {
      setTimeout(function () { beep(220, 0.06, "square", 0.035); }, 140);
      setTimeout(function () { beep(990, 0.05, "sine", 0.03); }, 220);
      setTimeout(function () { beep(140, 0.08, "sawtooth", 0.04); }, 300);
    }
    if (MARKET.talk === stall) paintTalkCard(stall);
    paintMarketHud();
    return true;
  }

