    const pathX = MARKET.w / 2;
    const TSCALE = 2.2;
    const tw = 74 * TSCALE, th = 48 * TSCALE;
    const destW0 = (74 + 36) * TSCALE;
    const fuel = stalls.find(function (st) { return st && st.kind === "shop" && st.shopType === "fuel"; });
    const sand = stalls.find(function (st) { return st && st.kind === "shop" && st.shopType === "sand"; });
