    if (jobList().some(function (j) { return j && j.legal === false; })) pool.push("Your alley paper's showing. Fold it.", "Illegal flavor. I don't stamp that either.");
    if (MARKET.event === "mixerRaid") pool.push("Tent's hot. Walk past like you meant to.");
    if (MARKET.event === "shadeDeal") pool.push("Crate's priced. Eyes elsewhere.");
    if (!MARKET.shadeSeen) MARKET.shadeSeen = [];
    let seen = MARKET.shadeSeen;
    if (seen.length >= pool.length) seen.length = 0;
    const unused = [];
    for (let i = 0; i < pool.length; i++) if (seen.indexOf(pool[i]) < 0) unused.push(pool[i]);
    const line = unused.length ? unused[(Math.random() * unused.length) | 0] : pick(pool);
