  function fountainSprite() {
    const pid = MARKET.planetId || "cardano";
    const vers = ["v3d", "v3c", "v3b", "v3", "v2"];
    for (let i = 0; i < vers.length; i++) {
      const spr = IM["fountain_" + pid + "_" + vers[i]];
      if (spr && !isStubArt(spr) && facadeLooksPainted(spr)) return spr;
    }
    return null;
  }
  function fountainOpaqueBox(spr) {
    if (!spr) return null;
    if (spr._opaqueBox) return spr._opaqueBox;
    const sw = spr.naturalWidth || spr.width || 1;
    const sh = spr.naturalHeight || spr.height || 1;
    const fallback = { sx: 0, sy: 0, sw: sw, sh: sh };
    try {
      const cap = 512;
      const scale = Math.min(1, cap / Math.max(sw, sh));
      const cw = Math.max(1, (sw * scale) | 0);
      const ch = Math.max(1, (sh * scale) | 0);
      const c = document.createElement("canvas");
      c.width = cw; c.height = ch;
      const x = c.getContext("2d", { willReadFrequently: true });
      x.drawImage(spr, 0, 0, cw, ch);
      const p = x.getImageData(0, 0, cw, ch).data;
      let l = cw, r = 0, t0 = ch, b = 0, found = 0;
      for (let i = 0, n = p.length; i < n; i += 4) {
        if (p[i + 3] > 12) {
          const px = (i / 4) % cw, py = ((i / 4) / cw) | 0;
          if (px < l) l = px; if (px > r) r = px;
          if (py < t0) t0 = py; if (py > b) b = py;
          found++;
        }
      }
      if (!found) { spr._opaqueBox = fallback; return fallback; }
      const inv = 1 / (scale || 1);
      let sx = Math.max(0, (l * inv) | 0);
      let sy = Math.max(0, (t0 * inv) | 0);
      let bw = Math.min(sw - sx, Math.ceil((r - l + 1) * inv));
      let bh = Math.min(sh - sy, Math.ceil((b - t0 + 1) * inv));
      spr._opaqueBox = { sx: sx, sy: sy, sw: bw, sh: bh };
      return spr._opaqueBox;
    } catch (e) {
      spr._opaqueBox = fallback;
      return fallback;
    }
  }
  function drawFountain(g, t, accent) {
    const f = MARKET.fountain;
    if (!f) return;
    const F = f.scale || 2.5;
    const destW = f.destW || 96 * F;
    const destH = f.destH || 78 * F;
    const sit = f.sit != null ? f.sit : Math.round(destH * 0.32);
    const destDx = -destW / 2;
    const destDy = -destH + sit;
    const st = streetStyle(MARKET.planetId || "cardano");
    withStreet(g, f.x, f.y, function () {
      const spr = fountainSprite();
      const painted = !!spr;
      if (painted) {
        try {
          const bb = fountainOpaqueBox(spr);
          g.drawImage(spr, bb.sx, bb.sy, bb.sw, bb.sh, destDx, destDy, destW, destH);
          loupeRegisterLocal(spr, f, destDx, destDy, destW, destH, 1, bb);
        } catch (e) {}
      } else {
        g.fillStyle = "#3a404c";
        g.beginPath(); g.ellipse(0, 6 * F, 26 * F, 8 * F, 0, 0, 6.28); g.fill();
        g.strokeStyle = "#5a6270";
        g.lineWidth = 2 * F;
        g.beginPath(); g.ellipse(0, 6 * F, 26 * F, 8 * F, 0, 0, 6.28); g.stroke();
        g.fillStyle = "#2a3038";
        g.beginPath(); g.ellipse(0, 5 * F, 20 * F, 5.5 * F, 0, 0, 6.28); g.fill();
      }
      const water = accent || st.neon;
      const waterLift = 28;
      g.save();
      for (let i = 0; i < 7; i++) {
        const a = -1.15 + i * 0.38;
        const life = (t * 2.15 + i * 0.14) % 1;
        const rise = -36 - waterLift - Math.sin(life * Math.PI) * 22;
        const out = Math.sin(a) * (6 + life * 18);
        g.strokeStyle = water;
        g.globalAlpha = 0.22 + (1 - life) * 0.55;
        g.lineWidth = 1.8 - life * 0.7;
        g.beginPath();
        g.moveTo(Math.cos(a) * 2.2, -24 - waterLift);
        g.quadraticCurveTo(Math.cos(a) * 5 + out * 0.2, rise, out, (-2 + life * 8) - waterLift);
        g.stroke();
      }
      for (let i = 0; i < 5; i++) {
        const life = (t * 1.6 + i * 0.2) % 1;
        g.globalAlpha = 0.12 + (1 - life) * 0.28;
        g.strokeStyle = "#d8f4ff";
        g.lineWidth = 0.9;
        g.beginPath();
        const x0 = -14 + i * 7;
        g.moveTo(x0, -20 - waterLift);
        g.bezierCurveTo(x0 - 2, (-8 - life * 6) - waterLift, x0 + 3, 0 - waterLift, x0 + Math.sin(t * 4 + i) * 2, 6 - waterLift);
        g.stroke();
      }
      g.globalAlpha = 0.42 + 0.18 * Math.sin(t * 5.2);
      g.fillStyle = water;
      g.beginPath(); g.ellipse(0, 5 - waterLift, 21 + Math.sin(t * 3.4) * 2.2, 5.6, 0, 0, 6.28); g.fill();
      g.globalAlpha = 0.22;
      g.fillStyle = "#f4fbff";
      g.beginPath(); g.ellipse(-6, 3.6 - waterLift, 8, 2.2, -0.2, 0, 6.28); g.fill();
      for (let r = 0; r < 4; r++) {
        const life = (t * 1.3 + r * 0.25) % 1;
        g.globalAlpha = 0.18 * (1 - life);
        g.strokeStyle = "#e8f6ff";
        g.lineWidth = 1;
        g.beginPath(); g.ellipse(0, 5 - waterLift, 10 + life * 16, 3 + life * 4.2, 0, 0, 6.28); g.stroke();
      }
      for (let i = 0; i < 22; i++) {
        const life = (t * 2.8 + i * 0.11) % 1;
        const ang = i * 0.74;
        const x = Math.cos(ang) * (4 + life * 20);
        const y = -22 - waterLift - Math.sin(life * Math.PI) * 18 + life * 28;
        g.globalAlpha = 0.25 + (1 - life) * 0.55;
        g.fillStyle = i % 3 ? water : "#f4fbff";
        g.beginPath(); g.arc(x, y, 0.7 + (1 - life) * 1.35, 0, 6.28); g.fill();
      }
      g.restore();
    });
  }
  function shopCrowdSpots(stall) {
    const roomH = shopRoomH();
    const roomW = MARKET.w;
    const kind = shopKind(stall);
    const clerk = shopClerkPos(kind, roomW, roomH);
    const toy = { x: roomW * 0.28, y: roomH * 0.46 };
    const spots = [];
    if (clerk) spots.push({ x: clerk.x - 40, y: clerk.y + 18 });
    spots.push(
      { x: toy.x, y: toy.y + 12 },
      { x: roomW * 0.18, y: roomH * 0.42 },
      { x: roomW * 0.82, y: roomH * 0.44 },
      { x: roomW * 0.50, y: roomH - 70 },
      { x: roomW * 0.34, y: roomH * 0.62 },
      { x: roomW * 0.66, y: roomH * 0.60 },
      { x: roomW * 0.50, y: roomH * 0.42 }
    );
    return spots;
  }
  function seedShopCrowd(stall) {
    const cast = (CROWD_CAST || []).concat(EXTRA_CAST || []);
    const spots = shopCrowdSpots(stall);
    const n = 6 + ((Math.random() * 2) | 0);
    const crowd = [];
    for (let i = 0; i < n; i++) {
      const look = Object.assign({}, cast[i % cast.length], { hat: "none", visor: "none", glasses: false, hoodie: false, robe: false, apron: null });
      const sp = spots[i % spots.length];
      crowd.push({
        id: "in" + i, name: look.name || "Walker",
        x: sp.x + rand(-12, 12), y: sp.y + rand(-8, 8),
        tx: sp.x, ty: sp.y,
        facing: rand(0, 6.28), walkT: Math.random() * 3,
        moving: false, state: "wander",
        timer: 0.3 + Math.random() * 1.2,
        puff: "", puffT: 0, look: look, spots: spots
      });
    }
    MARKET.shopCrowd = crowd;
  }
  function updateShopCrowd(dt) {
    const folks = MARKET.shopCrowd || [];
    if (!folks.length) return;
    const spots = folks[0].spots || shopCrowdSpots(MARKET.inside);
    for (let i = 0; i < folks.length; i++) {
      const c = folks[i];
      c.timer -= dt;
      if (c.puffT > 0) c.puffT -= dt;
      if (c.puffT <= 0) c.puff = "";
      const look = c.look || {};
      const sp = 56 * (look.gait || 1);
      if (c.state === "wander") {
        const dx = c.tx - c.x, dy = c.ty - c.y;
        const d = Math.hypot(dx, dy);
        if (d > 3) {
          c.x += (dx / d) * sp * dt;
          c.y += (dy / d) * sp * dt;
          c.facing = Math.atan2(dy, dx);
          c.moving = true;
          c.walkT += dt;
        } else {
          c.moving = false; c.walkT = 0;
        }
        if (c.timer <= 0) {
          const roll = Math.random();
          if (roll < 0.28) {
            c.state = "pause"; c.moving = false; c.timer = 0.8 + Math.random();
            if (Math.random() < 0.55) { c.puff = pickSoloTalkDeep(look, planetById(G.lastDock)); c.puffT = 3.6; }
          } else if (roll < 0.62) {
            let pal = null, pd = 48;
            for (let j = 0; j < folks.length; j++) {
              if (j === i) continue;
              const d2 = Math.hypot(c.x - folks[j].x, c.y - folks[j].y);
              if (d2 < pd) { pd = d2; pal = folks[j]; }
            }
            if (pal) {
              const beats = nextChatBeats(c, pal, planetById(G.lastDock));
              const cv = { beats: beats, i: 0, t: 0 };
              c.state = pal.state = "chat";
              c.convo = pal.convo = cv;
              c.buddy = pal.id; pal.buddy = c.id;
              c.timer = pal.timer = 2.0 * beats.length + 0.3;
              c.moving = pal.moving = false;
              c.facing = Math.atan2(pal.y - c.y, pal.x - c.x);
              pal.facing = Math.atan2(c.y - pal.y, c.x - pal.x);
              c.puff = beats[0] || ""; c.puffT = 2.2;
              pal.puff = ""; pal.puffT = 0;
            } else {
              const dest = spots[(Math.random() * spots.length) | 0];
              c.tx = dest.x + rand(-10, 10); c.ty = dest.y + rand(-8, 8);
              c.timer = 1.6 + Math.random();
            }
          } else {
            const dest = spots[(Math.random() * spots.length) | 0];
            c.tx = dest.x + rand(-10, 10); c.ty = dest.y + rand(-8, 8);
            c.timer = 1.8 + Math.random() * 1.4;
          }
        }
      } else if (c.state === "pause") {
        c.moving = false;
        if (c.timer <= 0) { c.state = "wander"; const dest = spots[(Math.random() * spots.length) | 0]; c.tx = dest.x; c.ty = dest.y; c.timer = 1.6; }
      } else if (c.state === "chat") {
        c.moving = false;
        const pal = folks.find(function (o) { return o.id === c.buddy; });
        if (pal) c.facing = Math.atan2(pal.y - c.y, pal.x - c.x);
        const cv = c.convo;
        if (cv && pal && cv.beats) {
          cv.t = (cv.t || 0) + dt;
          if (cv.t > 2.0 && cv.i < cv.beats.length - 1) {
            cv.i += 1; cv.t = 0;
            const speaker = (cv.i % 2 === 0) ? c : pal;
            const listener = speaker === c ? pal : c;
            speaker.puff = cv.beats[cv.i]; speaker.puffT = 2.2;
            listener.puff = ""; listener.puffT = 0;
          }
        }
        if (c.timer <= 0) {
          c.state = "wander"; c.buddy = null; c.convo = null;
          const dest = spots[(Math.random() * spots.length) | 0];
          c.tx = dest.x; c.ty = dest.y; c.timer = 1.5;
        }
      }
      if (MARKET.inside) clampShopFloor(c, false);
    }
  }
