        mctx.fillStyle = "rgba(232,65,66,0.06)";
        for (let y = wallH + 14; y < roomH; y += 22) mctx.fillRect(0, y, roomW, 1);
        // Crimson wall base trim
        mctx.fillStyle = "#E84142";
        mctx.globalAlpha = 0.55;
