        mctx.fillStyle = "#F7931A";
        mctx.globalAlpha = 0.35;
        mctx.fillRect(cx - 94, counterY + 4, 188, 4);
        mctx.globalAlpha = 1;
        mctx.strokeStyle = "rgba(247,147,26,0.28)";
