        const sky = mctx.createLinearGradient(0, 0, 0, roomH);
        sky.addColorStop(0, "#050a18");
        sky.addColorStop(0.35, "#0a1430");
        sky.addColorStop(1, "#040812");
        mctx.fillStyle = sky;
        mctx.fillRect(0, 0, roomW, roomH);
        mctx.fillStyle = "#0a1220";
        mctx.fillRect(0, wallH, roomW, roomH - wallH);
