        mctx.fillStyle = "rgba(98,126,234,0.10)"; mctx.fillRect(44, 40, 64, 92); mctx.fillRect(roomW - 108, 40, 64, 92);
        mctx.fillStyle = "#1a1e32"; mctx.fillRect(cx - 90, counterY + 8, 180, 14);
