        mctx.strokeStyle = "rgba(20,241,149,0.30)"; mctx.lineWidth = 1.4;
        mctx.strokeRect(40, 36, 72, 100); mctx.strokeRect(roomW - 112, 36, 72, 100);
        mctx.fillStyle = "rgba(153,69,255,0.12)"; mctx.fillRect(44, 40, 64, 92); mctx.fillRect(roomW - 108, 40, 64, 92);
        mctx.fillStyle = "#1a162e"; mctx.fillRect(cx - 90, counterY + 8, 180, 14);
        mctx.fillStyle = "#9945FF"; mctx.globalAlpha = 0.35; mctx.fillRect(cx - 94, counterY + 4, 188, 4); mctx.globalAlpha = 1;
        mctx.fillStyle = "rgba(20,241,149,0.55)"; mctx.font = "bold 13px sans-serif"; mctx.textAlign = "center";
