  function resumeArmed() {
    if (selectMode !== "resume" || !continuePilot) return null;
    const row = rosterFind(G.pilot || readPilotInput());
    return (row && row.save) ? row : null;
  }
  function paintLaunchButton() {
    const btn = $("launchBtn");
    if (!btn) return;
    const span = btn.querySelector("span");
    const hint = btn.querySelector(".launch-hint") || $("launchHint");
    const row = resumeArmed();
    const resume = !!row;
    btn.classList.toggle("resume", resume);
    if (span) span.textContent = resume ? "RESUME" : "LAUNCH";
    if (resume) {
      const sv = row.save || {};
      const fac = FACTIONS[sv.selectedId || sv.homeFaction] || FACTIONS.ada;
      const line = (row.name || G.pilot || "Pilot") + " · " + (fac.tick || "") + " · " + walletLine(sv.credits);
      if (hint) hint.textContent = line;
      btn.style.borderColor = "#3DDC84";
    } else {
      const f = FACTIONS[selectedId] || FACTIONS.ada;
      if (hint) hint.textContent = "Click a ship";
      btn.style.borderColor = f.color;
    }
  }
  function paintLaunchArt(id) {
    const art = $("launchArt");
    const btn = $("launchBtn");
    const f = FACTIONS[id];
    if (!art || !f) return;
    paintLaunchButton();
    if (btn && !btn.classList.contains("resume")) btn.style.borderColor = f.color;
    const g = art.getContext("2d");
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.clearRect(0, 0, art.width, art.height);
    g.translate(art.width / 2, art.height / 2 + 4);
    const t = G.tier || 1;
    const spr = hullSprite(id, t);
    if (spr && (spr.width || spr.naturalWidth)) {
      const iw = spr.width || spr.naturalWidth, ih = spr.height || spr.naturalHeight;
      const noseUp = id === "atom";
      const sc = noseUp
        ? Math.min((art.height - 8) / iw, (art.width - 8) / ih)
        : Math.min((art.height - 8) / ih, (art.width - 8) / iw);
      const w = iw * sc, h = ih * sc;
      if (noseUp) {
        g.save();
        g.rotate(-Math.PI / 2);
        try { g.drawImage(spr, -w / 2, -h / 2, w, h); } catch (e) {}
        g.restore();
      } else {
        try { g.drawImage(spr, -w / 2, -h / 2, w, h); } catch (e) {}
      }
      return;
    }
    if (id === "ada") {
      const skin = adaSkin();
      const fb = (skin && skin.canvas) || ADA.sprite || IM.adaRocket || IM.adaWide;
      if (fb && (fb.width || fb.naturalWidth)) {
        const iw = fb.width || fb.naturalWidth, ih = fb.height || fb.naturalHeight;
        const h = art.height - 8, w = (iw / ih) * h;
        try { g.drawImage(fb, -w / 2, -h / 2, w, h); } catch (e) {}
        g.rotate(-Math.PI / 2);
        g.scale(1.35, 1.35);
        drawAdaTierBits(g, t);
        return;
      }
    }
    g.rotate(-Math.PI / 2);
    g.scale(2.15, 2.15);
    drawFactionHull(g, id, t, { trail: false, noFlame: true });
  }

  function paintAdaHull() {
    const dd = $("adaHullDd");
    const menu = $("adaHullDdMenu");
    const val = $("adaHullDdVal");
    const show = selectedId === "ada" && customWho() === "you";
    if (dd) dd.classList.toggle("hidden", !show);
    if (!show) {
      if (menu) menu.innerHTML = "";
      return;
    }
    const cur = validAdaSkin(ADA.skinId);
    ADA.skinId = cur;
    const def = ADA_SKINS.find(function (k) { return k.id === cur; });
    if (val) val.textContent = def ? def.name.toUpperCase() : "ADA ROCKET";
    if (!menu) return;
    menu.innerHTML = "";
    ADA_SKINS.forEach(function (k) {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "dd-item" + (cur === k.id ? " on" : "");
      const sk = ADA.skins[k.id];
      const tThumb = G.tier || 1;
      const spr = (sk && sk.tiers && sk.tiers[tThumb]) || (sk && sk.canvas);
      if (spr && (spr.width || spr.naturalWidth)) {
        const cv = document.createElement("canvas");
        cv.width = 36;
        cv.height = 40;
        const gx = cv.getContext("2d");
        const iw = spr.width || spr.naturalWidth, ih = spr.height || spr.naturalHeight;
        const h = 36, w = (iw / ih) * h;
        try { gx.drawImage(spr, 18 - w / 2, 20 - h / 2, w, h); } catch (e) {}
        btn.appendChild(cv);
      }
      const tag = document.createElement("span");
      tag.textContent = k.name.toUpperCase();
      btn.appendChild(tag);
      btn.addEventListener("click", function (e) {
        e.stopPropagation();
        closeCustomizeMenus();
        selectAdaSkin(k.id);
      });
      menu.appendChild(btn);
    });
  }

