      gx.translate(ec.width / 2, ec.height * 0.82);
      const sc = Math.min(ec.width / 28, ec.height / 46);
      gx.scale(sc, sc);
      drawPerson(gx, 0, 0, epochPersonOpt({ scale: 1, wheelFace: 1, wheelAng: 0.4, lean: 0 }));
