  function paintScoutThumb(gx, id, size) {
    size = size || 72;
    gx.setTransform(1, 0, 0, 1, 0, 0);
    gx.clearRect(0, 0, size, size);
    // Match launchArt fit math so bubbles stay sharp (was tiny pad + soft CSS upscale).
    const spr = hullSprite(id, 1);
    if (spr && (spr.width || spr.naturalWidth)) {
      const iw = spr.width || spr.naturalWidth, ih = spr.height || spr.naturalHeight;
      const pad = 4;
      const noseUp = id === "atom";
      const sc = noseUp
        ? Math.min((size - pad * 2) / iw, (size - pad * 2) / ih)
        : Math.min((size - pad * 2) / ih, (size - pad * 2) / iw);
      const dw = iw * sc, dh = ih * sc;
      gx.save();
      gx.translate(size / 2, size / 2);
      if (noseUp) gx.rotate(-Math.PI / 2);
      try { gx.drawImage(spr, -dw / 2, -dh / 2, dw, dh); } catch (e) {}
      gx.restore();
      return;
    }
    gx.save();
    gx.translate(size / 2, size / 2 + 4);
    gx.rotate(-Math.PI / 2);
    drawFactionHull(gx, id, 1, { trail: false });
    gx.restore();
  }
  function refreshOrbitThumb(id) {
    const node = document.querySelector('.ship-node[data-id="' + id + '"]');
    if (!node) return;
    const cv = node.querySelector("canvas");
    if (!cv) return;
    paintScoutThumb(cv.getContext("2d"), id, cv.width);
  }
  function layoutOrbit() {
    const orbit = $("shipOrbit");
    if (!orbit) return;
    const nodes = orbit.querySelectorAll(".ship-node");
    const n = nodes.length;
    const ang = ORBIT.ang || 0;
    nodes.forEach(function (node, i) {
      const a = -Math.PI / 2 + (i / n) * Math.PI * 2 + ang;
      node.style.left = (50 + Math.cos(a) * 42) + "%";
      node.style.top = (50 + Math.sin(a) * 36) + "%";
    });
    orbit.classList.toggle("spinning", ORBIT.drag || Math.abs(ORBIT.vel) > 0.08);
  }
  function orbitAngleAt(e, el) {
    const r = el.getBoundingClientRect();
    return Math.atan2(e.clientY - (r.top + r.height * 0.5), e.clientX - (r.left + r.width * 0.5));
  }
  function spawnOrbitFx(el) {
    if (!el) return;
    const r = el.getBoundingClientRect();
    const cx = r.left + r.width * 0.5, cy = r.top + r.height * 0.5;
    for (let i = 0; i < 3; i++) {
      const a = Math.random() * 6.28;
      const rad = r.width * (0.28 + Math.random() * 0.16);
      ORBIT.fx.push({
        x: (cx + Math.cos(a) * rad - r.left) / r.width,
        y: (cy + Math.sin(a) * rad - r.top) / r.height,
        life: 0.35 + Math.random() * 0.25,
        gold: Math.random() > 0.55
      });
    }
    if (ORBIT.fx.length > 36) ORBIT.fx.splice(0, ORBIT.fx.length - 36);
  }
  function updateSelectOrbit(dt) {
    if (!ORBIT.drag) {
      if (Math.abs(ORBIT.vel) > 0.012) {
        ORBIT.ang += ORBIT.vel * dt;
        ORBIT.vel *= Math.pow(0.14, dt);
        if (Math.random() < 0.55) spawnOrbitFx($("shipOrbit"));
      } else ORBIT.vel = 0;
    }
    G.orbitAng = ORBIT.ang;
    layoutOrbit();
    paintSelectSky();
  }
  function paintSelectSky() {
    const cv = $("selectSky");
    if (!cv) return;
    const wrap = $("screen-select");
    if (!wrap) return;
    const w = wrap.clientWidth || 960, h = wrap.clientHeight || 540;
    if (cv.width !== w || cv.height !== h) { cv.width = w; cv.height = h; }
    const g = cv.getContext("2d");
    g.clearRect(0, 0, w, h);
    for (let i = 0; i < SELECT_STARS.length; i++) {
      const s = SELECT_STARS[i];
      const tw = 0.42 + 0.58 * Math.sin((G.time || 0) * 3.6 + s.p);
      g.globalAlpha = s.a * tw;
      g.fillStyle = tw > 0.82 ? "#F5C542" : "#e8f4ff";
      const px = s.x * w, py = s.y * h;
      g.fillRect(px, py, s.s, s.s);
    }
    g.globalAlpha = 1;
    const t = G.time || 0;
    const dtSel = 0.016;
    // Light select-screen dogfights: a few ships occasionally fire at a rival faction.
    for (let i = 0; i < SELECT_FLY.length; i++) {
      const f = SELECT_FLY[i];
      f.x += f.vx * dtSel;
      f.y += f.vy * dtSel;
      if (f.x < -0.14) f.x = 1.14;
      if (f.x > 1.14) f.x = -0.14;
      if (f.y < -0.10) f.y = 0.94;
      if (f.y > 1.10) f.y = 0.06;
      f.fireCd = (f.fireCd || 0) - dtSel;
      if (f.foe && f.fireCd <= 0 && SELECT_SHOT.length < 18) {
        let best = null, bestD = 0.22;
        for (let j = 0; j < SELECT_FLY.length; j++) {
          if (j === i) continue;
          const o = SELECT_FLY[j];
          if (o.faction === f.faction) continue;
          const dx = o.x - f.x, dy = o.y - f.y;
          const d = Math.hypot(dx, dy);
          if (d < bestD) { bestD = d; best = o; }
        }
        if (best) {
          const dx = best.x - f.x, dy = best.y - f.y;
          const len = Math.hypot(dx, dy) || 1;
          const col = (FACTIONS[f.faction] || FACTIONS.ada).color;
          SELECT_SHOT.push({
            x: f.x, y: f.y,
            vx: (dx / len) * 0.55, vy: (dy / len) * 0.55,
            life: 0.85, col: col, faction: f.faction
          });
          f.fireCd = rand(1.1, 2.8);
        } else {
          f.fireCd = rand(0.6, 1.4);
        }
      }
    }
    for (let i = SELECT_SHOT.length - 1; i >= 0; i--) {
      const s = SELECT_SHOT[i];
      s.x += s.vx * dtSel;
      s.y += s.vy * dtSel;
      s.life -= dtSel;
      if (s.life <= 0 || s.x < -0.2 || s.x > 1.2 || s.y < -0.2 || s.y > 1.2) {
        SELECT_SHOT.splice(i, 1);
        continue;
      }
      const px = s.x * w, py = s.y * h;
      g.save();
      g.globalAlpha = Math.max(0.15, Math.min(0.95, s.life * 1.2));
      g.fillStyle = s.col || "#7ad7ff";
      g.beginPath();
      g.arc(px, py, 2.2, 0, 6.28);
      g.fill();
      g.strokeStyle = s.col || "#7ad7ff";
      g.lineWidth = 1.2;
      g.globalAlpha *= 0.55;
      g.beginPath();
      g.moveTo(px, py);
      g.lineTo(px - s.vx * w * 0.08, py - s.vy * h * 0.08);
      g.stroke();
      g.restore();
    }
    for (let i = 0; i < SELECT_FLY.length; i++) {
      const f = SELECT_FLY[i];
      const px = f.x * w, py = f.y * h;
      const ang = Math.atan2(f.vy * h, f.vx * w);
      const spr = hullSprite(f.faction, f.tier, f.skin);
      const pulse = 0.94 + 0.06 * Math.sin(t * 1.5 + f.p);
      g.save();
      g.translate(px, py);
      // Nose-up hull art: same +PI/2 convention as drawShip afterburner sprites.
      // Cosmos (atom) sheets are already nose-up — extra -PI/2 (= 90° CCW from prior).
      g.rotate(ang + Math.PI / 2);
      if (f.faction === "atom") g.rotate(-Math.PI / 2);
      g.globalAlpha = f.a * pulse;
      if (spr && (spr.width || spr.naturalWidth)) {
        const fit = hullFitSize(spr, f.size * pulse);
        try { g.drawImage(spr, -fit.w / 2, -fit.h / 2, fit.w, fit.h); } catch (e) {}
      } else {
        const col = (FACTIONS[f.faction] || FACTIONS.ada).color;
        const sc = f.size * 0.45;
        g.strokeStyle = col;
        g.fillStyle = col;
        g.globalAlpha *= 0.55;
        g.lineWidth = 1.2;
        g.beginPath();
        g.moveTo(0, -sc * 0.72);
        g.lineTo(sc * 0.38, sc * 0.42);
        g.lineTo(0, sc * 0.18);
        g.lineTo(-sc * 0.38, sc * 0.42);
        g.closePath();
        g.stroke();
      }
      g.restore();
    }
    g.globalAlpha = 1;
    const orbit = $("shipOrbit");
    if (orbit && (ORBIT.drag || Math.abs(ORBIT.vel) > 0.08 || ORBIT.fx.length)) {
      const r = orbit.getBoundingClientRect();
      const wr = wrap.getBoundingClientRect();
      const ox = r.left - wr.left + r.width * 0.5;
      const oy = r.top - wr.top + r.height * 0.5;
      const glow = g.createRadialGradient(ox, oy, r.width * 0.18, ox, oy, r.width * 0.46);
      glow.addColorStop(0, "rgba(0,195,255,0)");
      glow.addColorStop(0.62, "rgba(0,195,255,0.06)");
      glow.addColorStop(0.82, "rgba(245,197,66,0.08)");
      glow.addColorStop(1, "rgba(0,0,0,0)");
      g.fillStyle = glow;
      g.beginPath(); g.arc(ox, oy, r.width * 0.46, 0, 6.28); g.fill();
    }
    let fxOx = 0, fxOy = 0, fxOw = w, fxOh = h;
    if (orbit) {
      const or = orbit.getBoundingClientRect();
      const wr = wrap.getBoundingClientRect();
      fxOx = or.left - wr.left;
      fxOy = or.top - wr.top;
      fxOw = or.width;
      fxOh = or.height;
    }
    for (let i = ORBIT.fx.length - 1; i >= 0; i--) {
      const f = ORBIT.fx[i];
      f.life -= 0.016;
      if (f.life <= 0) { ORBIT.fx.splice(i, 1); continue; }
      g.globalAlpha = Math.max(0, f.life * 1.4);
      g.fillStyle = f.gold ? "#F5C542" : "#00C3FF";
      g.beginPath();
      g.arc(fxOx + f.x * fxOw, fxOy + f.y * fxOh, 1.15, 0, 6.28);
      g.fill();
    }
    g.globalAlpha = 1;
  }
  function bindOrbitFling() {
    const orbit = $("shipOrbit");
    if (!orbit || orbit.dataset.fling) return;
    orbit.dataset.fling = "1";
    function onDown(e) {
      if (e.target && e.target.closest && e.target.closest("#launchBtn")) return;
      const node = e.target && e.target.closest ? e.target.closest(".ship-node") : null;
      ORBIT.drag = true;
      ORBIT.moved = false;
      ORBIT.node = node ? node.dataset.id : null;
      ORBIT.lastA = orbitAngleAt(e, orbit);
      ORBIT.lastT = performance.now();
      ORBIT.vel = 0;
      orbit.classList.add("spinning");
      e.preventDefault();
    }
    function onMove(e) {
      if (!ORBIT.drag) return;
      const a = orbitAngleAt(e, orbit);
      let d = a - ORBIT.lastA;
      while (d > Math.PI) d -= Math.PI * 2;
      while (d < -Math.PI) d += Math.PI * 2;
      const now = performance.now();
      const dt = Math.max(0.008, (now - ORBIT.lastT) / 1000);
      ORBIT.ang += d;
      ORBIT.vel = d / dt;
      if (Math.abs(d) > 0.012) ORBIT.moved = true;
      ORBIT.lastA = a;
      ORBIT.lastT = now;
      spawnOrbitFx(orbit);
      layoutOrbit();
    }
    function onUp() {
      if (!ORBIT.drag) return;
      ORBIT.drag = false;
      ORBIT.vel = clamp(ORBIT.vel, -10, 10);
      if (!ORBIT.moved && ORBIT.node) selectShip(ORBIT.node);
      ORBIT.node = null;
      G.orbitAng = ORBIT.ang;
    }
    orbit.addEventListener("pointerdown", onDown);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
  }
  function buildSelect() {
    const orbit = $("shipOrbit");
    orbit.innerHTML = "";
    const ids = FACTION_IDS;
    const n = ids.length;
    if (G.orbitAng != null && isFinite(+G.orbitAng)) ORBIT.ang = +G.orbitAng;
    ids.forEach((id, i) => {
      const node = document.createElement("button");
      node.type = "button";
      node.className = "ship-node" + (id === "ada" ? " ada-home" : "") + (id === selectedId ? " active" : "");
      node.dataset.id = id;
      const cv = document.createElement("canvas");
      // Hi-DPI bitmap so CSS ~108px circle stays crisp (was 96).
      cv.width = 192;
      cv.height = 192;
      paintScoutThumb(cv.getContext("2d"), id, 192);
      node.appendChild(cv);
      const cap = document.createElement("span");
      cap.className = "ship-name";
      cap.textContent = (FACTIONS[id] && FACTIONS[id].name) || id;
      node.appendChild(cap);
      orbit.appendChild(node);
    });
    layoutOrbit();
    bindOrbitFling();
    paintLaunchArt(selectedId);
    paintLaunchButton();
    paintSelectInfo();
    paintAdaSkins();
    paintSelectSky();
  }

  function selectShip(id) {
    selectedId = id;
    G.homeFaction = id;
    document.querySelectorAll(".ship-node").forEach(n => n.classList.toggle("active", n.dataset.id === id));
    paintLaunchArt(id);
    paintLaunchButton();
    paintSelectInfo();
    paintAdaSkins();
    beep(400, 0.05, "sine", 0.04);
  }

  function paintSelectInfo() {
    $("selName").textContent = SHIPS[selectedId].name;
    const tick = FACTIONS[selectedId].tick;
    $("selBlurb").textContent = SHIPS[selectedId].blurb;
    paintLookRow();
  }

  const SCORE_KEY = "cosmicVoyager.scores";
  const INI_KEY = "cosmicVoyager.initials";

  function missionsDoneCount() {
    return Object.keys(G.done || {}).length;
  }

  function runScore() {
    return ((G.earned | 0) + (G.xp | 0) * 2 + missionsDoneCount() * 150 + ((G.tier || 1) - 1) * 250) | 0;
  }

  function lastInitials() {
    try {
      const v = (localStorage.getItem(INI_KEY) || "RYN").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 3);
      return v || "RYN";
    } catch (e) { return "RYN"; }
  }

  function loadScores() {
    try {
      const a = JSON.parse(localStorage.getItem(SCORE_KEY) || "[]");
      return Array.isArray(a) ? a : [];
    } catch (e) { return []; }
  }

  function postScore(ini) {
    ini = String(ini || "RYN").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 3);
    if (ini.length < 3) ini = (ini + "RYN").slice(0, 3);
    try { localStorage.setItem(INI_KEY, ini); } catch (e) {}
    const row = { ini: ini, score: runScore(), ship: selectedId || G.homeFaction || "ada", t: Date.now() };
    const list = loadScores();
    list.push(row);
    list.sort((a, b) => (b.score | 0) - (a.score | 0) || (b.t | 0) - (a.t | 0));
    try { localStorage.setItem(SCORE_KEY, JSON.stringify(list.slice(0, 8))); } catch (e) {}
  }

  function paintScoreboard() {
    const el = $("scoreboardList");
    if (!el) return;
    const list = loadScores().slice(0, 8);
    if (!list.length) {
      el.innerHTML = "<li class='empty'>No runs posted</li>";
      return;
    }
    el.innerHTML = list.map(r => "<li><b>" + (r.ini || "???") + "</b><span>" + (r.score | 0) + "</span></li>").join("");
  }

  function hideIniPrompt() {
    const el = $("iniPrompt");
    if (el) el.classList.add("hidden");
  }

  function showIniPrompt() {
    const el = $("iniPrompt");
    if (!el) { goSelect(); return; }
    if ($("iniScore")) $("iniScore").textContent = String(runScore());
    const inp = $("iniInput");
    if (inp) { inp.value = lastInitials(); }
    el.classList.remove("hidden");
    mode = "ini";
    if (inp) { try { inp.focus(); inp.select(); } catch (e) {} }
  }

  function finishIni(doPost) {
    hideIniPrompt();
    if (doPost) postScore(($("iniInput") && $("iniInput").value) || lastInitials());
    goSelect();
  }

  function goSelect() {
    hideIniPrompt();
    mode = "select";
    showScreen("select");
    loadGame();
    try {
      const active = localStorage.getItem(ACTIVE_KEY) || G.pilot || lastInitials();
      if ($("pilotName") && !$("pilotName").value) $("pilotName").value = active || "";
      continuePilot = false;
    } catch (e) {}
    G.lookExtra = G.lookExtra || {};
    G.lookExtra.visor = "none";
    G.lookExtra.hat = "none";
    ADA.skinId = validAdaSkin(ADA.skinId);
    buildSelect();
    paintSelectInfo();
    paintScoreboard();
    paintLookRow();
    setSelectMode("new");
  }

  window.addEventListener("keydown", (e) => {
    if (e.code === "Tab") e.preventDefault();
    keys[e.key.length === 1 ? e.key.toLowerCase() : e.key] = true;
    if (e.code === "Space") keys[" "] = true;
    if (e.key === "Shift") keys.Shift = true;
    if (e.code === "Tab") keys.Tab = true;
    if (mode === "ini") {
      if (e.key === "Enter") { e.preventDefault(); finishIni(true); }
      return;
    }
    if (mode === "select") {
      const typing = document.activeElement && document.activeElement.id === "pilotName";
      if (typing) {
        if (e.key === "Enter") { e.preventDefault(); launch(selectedId); }
        return;
      }
      const map = { "1": "ada", "2": "btc", "3": "eth", "4": "sol", "5": "pol", "6": "doge", "7": "xrp", "8": "atom", "9": "ltc", "0": "avax" };
      if (map[e.key]) selectShip(map[e.key]);
      if (e.key === "Enter") launch(selectedId);
    }
    if ((e.key === "p" || e.key === "P") && (mode === "play" || mode === "map" || mode === "market")) toggleAutopilot();
    if ((e.key === "t" || e.key === "T") && (mode === "play" || mode === "map")) tryQuantumHop();
    if (mode === "play" && (e.key === "q" || e.key === "Q" || e.key === "]")) cycleWeapon(1);
    if (mode === "play" && e.key === "[") cycleWeapon(-1);
    if (e.key === "n" || e.key === "N") {
      audio.muted = !audio.muted;
      toast(audio.muted ? "Audio muted" : "Audio on");
    }
    if (e.key === "f" || e.key === "F") {
      e.preventDefault();
      if (mode === "market" && MARKET.secretAnnex && secretAnnexFromDeep()) tryDeepLook();
      if (mode === "market" && MARKET.secretAnnex && MARKET.secretReturn && MARKET.secretReturn.from === "towerBalcony") {
        // LOOK · F on balcony: tomato can (Doge) or rail flavor
        if (!tryBalconyTomatoCan()) {
          toast(pick([
            "Rail looks back. Scrap stays taped.",
            "Vacuum through the bars. Suit still required.",
            "You look. The planet looks louder."
          ]));
          beep(480, 0.05, "sine", 0.03);
        }
      }
      else toggleFullscreen();
    }
    if ((e.key === "k" || e.key === "K") && (mode === "play" || mode === "market" || mode === "map")) {
      toggleEpochFollow();
    }
    if ((e.key === "l" || e.key === "L") && mode === "market") {
      toggleLoupeLook();
    }
    if (mode === "duel") {
      if (e.key === "1" || e.key === "j" || e.key === "J") { duelPlayerCommand("strike"); return; }
      if (e.key === "2" || e.key === "k" || e.key === "K") { duelPlayerCommand("guard"); return; }
      if (e.key === "3" || e.key === "l" || e.key === "L") { duelPlayerCommand("steal"); return; }
      if (e.key === "4") {
        if (G.duel && duelBoostUnlocked(G.pilotStr)) duelPlayerCommand("boost");
        return;
      }
    }
    if ((e.key === "i" || e.key === "I") && (mode === "play" || mode === "market" || mode === "map")) {
      if (mode !== "loot" && mode !== "duel") toggleInventory();
    }
    if (e.key === "e" || e.key === "E") {
      if (mode === "play") {
        const lm = LANDMARKS.find(function (l) { return G.player && dist(G.player, l) < l.r + 70; });
        if (lm && lm.kind === "ghost") tryRadioHack();
        else openDock();
      }
      else if (mode === "market") marketInteract();
    }
    if ((e.key === "c" || e.key === "C") && (mode === "play" || mode === "tut" || mode === "map")) {
      if (!G.radioHack) toast("Ghost has not spoken for you.");
    }
    if (e.key === "m" || e.key === "M") {
      if (mode === "play") { mode = "map"; showScreen("map"); drawMap(); clearKeys(); }
      else if (mode === "map") { mode = "play"; showScreen("play"); }
    }
    if (e.key === "Escape") {
      if (mode === "duel") { duelRequestFlee(); return; }
      if (mode === "loot") { closeLootSheet(true); return; }
      if (isInvOpen()) { closeInventory(); return; }
      if (mode === "play") { mode = "pause"; showScreen("pause"); clearKeys(); }
      else if (mode === "pause") { mode = "play"; showScreen("play"); }
      else if (mode === "map") { mode = "play"; showScreen("play"); }
      else if (mode === "market") {
        if (MARKET.kiosk) closeKiosk(true);
        else if (MARKET.talk) closeTalk(true);
        else if (MARKET.paper) togglePaperDock(false);
        else if (MARKET.inside) {
          if (MARKET.secretAnnex || shopKind(MARKET.inside) === "secret") exitSecretAnnex();
          else exitShop();
        }
        else undock();
      }
      else if (mode === "dock") undock();
    }
    /* Tab is ship special in flight only — paper is the info booth now. */
    /* Boarding: hold B near soft ships (see updateBoarding). */
  });
  window.addEventListener("keyup", (e) => {
    keys[e.key.length === 1 ? e.key.toLowerCase() : e.key] = false;
    if (e.code === "Space") keys[" "] = false;
    if (e.key === "Shift") keys.Shift = false;
    if (e.code === "Tab") keys.Tab = false;
  });
  window.addEventListener("resize", () => { if (mode === "market") resizeMarket(); });
  window.addEventListener("blur", clearKeys);
  canvas.addEventListener("mousemove", (e) => {
    const r = canvas.getBoundingClientRect();
    const rw = r.width || W, rh = r.height || H;
    const mx = (e.clientX - r.left) * (W / rw);
    const my = (e.clientY - r.top) * (H / rh);
    if (Math.hypot(mx - mouse.x, my - mouse.y) > 1.5) lastMouseMove = G.time || 0;
    mouse.x = mx;
    mouse.y = my;
  });
  if (mcanvas) {
    mcanvas.addEventListener("mousemove", function (e) {
      readMarketMouse(e);
      if (G.gotLoupe && G.loupeHeld && MARKET.loupeDrag && mode === "market") {
        ensureLoupePrefs();
        const base = MARKET.loupeZoomBase || 2.5;
        const dy = MARKET.loupeDrag.startY - e.clientY;
        const next = MARKET.loupeDrag.startZoom + (dy / 140) * base;
        MARKET.loupeZoom = clamp(next, base, base * 2);
      }
    });
    mcanvas.addEventListener("mousedown", function (e) {
      if (mode !== "market") return;
      if (e.button === 0 && G.gotLoupe && G.loupeHeld) {
        ensureLoupePrefs();
        MARKET.loupeDrag = { startY: e.clientY, startZoom: MARKET.loupeZoom || MARKET.loupeZoomBase || 2.5 };
        e.preventDefault();
      } else if (e.button === 2 && G.gotLoupe && G.loupeHeld) {
        e.preventDefault();
        stowLoupe("Glass down.");
      }
    });
    mcanvas.addEventListener("mouseup", function (e) {
      if (e.button === 0) MARKET.loupeDrag = null;
    });
    mcanvas.addEventListener("mouseleave", function () {
      MARKET.loupeDrag = null;
      if (!(G.gotLoupe && G.loupeHeld)) setLoupeCursor();
    });
    mcanvas.addEventListener("wheel", function (e) {
      if (!(mode === "market" && G.gotLoupe && G.loupeHeld)) return;
      e.preventDefault();
      ensureLoupePrefs();
      const step = e.deltaY > 0 ? -6 : 6;
      MARKET.loupeR = clamp((MARKET.loupeR || 54) + step, 54, 162);
    }, { passive: false });
    mcanvas.addEventListener("contextmenu", function (e) {
      if (mode === "market" && G.gotLoupe && G.loupeHeld) e.preventDefault();
    });
  }
  if ($("invClose")) $("invClose").addEventListener("click", function () { closeInventory(); });
  canvas.addEventListener("mousedown", () => { mouse.down = true; audioCtx(); });
  window.addEventListener("mouseup", (e) => {
    mouse.down = false;
    MARKET.loupeDrag = null;
    if (mode === "map" && MAPVIEW.drag && (MAPVIEW.moved || 0) < 8) handleMapClick(e);
    MAPVIEW.drag = false;
    if (mapC) mapC.classList.remove("drag");
  });

  if (mapC) {
    mapC.addEventListener("wheel", (e) => {
      if (mode !== "map") return;
      e.preventDefault();
      const rect = mapC.getBoundingClientRect();
      const mx = (e.clientX - rect.left) * (mapC.width / (rect.width || 1));
      const my = (e.clientY - rect.top) * (mapC.height / (rect.height || 1));
      const before = screenToMap(mx, my);
      const next = clamp(MAPVIEW.zoom * (e.deltaY < 0 ? 1.12 : 1 / 1.12), 0.6, 3);
      MAPVIEW.zoom = next;
      const after = screenToMap(mx, my);
      MAPVIEW.cx += before.x - after.x;
      MAPVIEW.cy += before.y - after.y;
      clampMapView();
    }, { passive: false });
    mapC.addEventListener("mousedown", (e) => {
      if (mode !== "map") return;
      if (e.button === 0 || e.button === 2) {
        MAPVIEW.drag = true;
        MAPVIEW.lx = e.clientX;
        MAPVIEW.ly = e.clientY;
        MAPVIEW.ax = e.clientX;
        MAPVIEW.ay = e.clientY;
        MAPVIEW.moved = 0;
        mapC.classList.add("drag");
        e.preventDefault();
      }
    });
    window.addEventListener("mousemove", (e) => {
      if (!MAPVIEW.drag || mode !== "map") return;
      MAPVIEW.moved = (MAPVIEW.moved || 0) + Math.hypot(e.clientX - MAPVIEW.lx, e.clientY - MAPVIEW.ly);
      const rect = mapC.getBoundingClientRect();
      const sc = mapScale() || 0.001;
      const css = mapC.width / (rect.width || 1);
      MAPVIEW.cx -= (e.clientX - MAPVIEW.lx) * css / sc;
      MAPVIEW.cy -= (e.clientY - MAPVIEW.ly) * css / sc;
      MAPVIEW.lx = e.clientX;
      MAPVIEW.ly = e.clientY;
      clampMapView();
    });
    mapC.addEventListener("contextmenu", (e) => {
      if (mode === "map") e.preventDefault();
    });
  }

  if ($("apPill")) $("apPill").addEventListener("click", function () { toggleAutopilot(); });
  $("launchBtn").addEventListener("click", () => launch(selectedId));
